    public static function customer_detail(WP_REST_Request $request){$customer=self::get_customer($request);return is_wp_error($customer)?$customer:rest_ensure_response(self::serialize_customer($customer));}
    public static function update_customer(WP_REST_Request $request){
        $customer=self::get_customer($request);if(is_wp_error($customer))return $customer;$p=(array)$request->get_json_params();foreach(['first_name','last_name'] as $field){if(array_key_exists($field,$p)){$method='set_'.$field;$customer->{$method}(sanitize_text_field((string)$p[$field]));}}if(array_key_exists('email',$p)){if(!is_email($p['email']))return new WP_Error('invalid_email','ایمیل معتبر نیست.',['status'=>422]);try{$customer->set_email(sanitize_email($p['email']));}catch(Exception $e){return new WP_Error('email_exists',$e->getMessage(),['status'=>422]);}}
        foreach(['billing','shipping'] as $type){if(!isset($p[$type])||!is_array($p[$type]))continue;foreach(['first_name','last_name','company','address_1','address_2','city','state','postcode','country'] as $field){if(array_key_exists($field,$p[$type])){$method='set_'.$type.'_'.$field;$customer->{$method}(sanitize_text_field((string)$p[$type][$field]));}}}if(isset($p['billing']['phone']))$customer->set_billing_phone(sanitize_text_field((string)$p['billing']['phone']));if(isset($p['billing']['email'])&&is_email($p['billing']['email']))$customer->set_billing_email(sanitize_email($p['billing']['email']));
        try{$customer->save();return rest_ensure_response(self::serialize_customer($customer));}catch(Throwable $e){return new WP_Error('customer_update_failed',$e->getMessage(),['status'=>500]);}
    }
    public static function report_summary(WP_REST_Request $request){
        if(!function_exists('wc_get_orders'))return new WP_Error('woocommerce_missing','ووکامرس فعال نیست.',['status'=>503]);$days=(int)$request->get_param('days');if(!in_array($days,[7,30,90],true))$days=30;$timezone=wp_timezone();$today=new DateTimeImmutable('today',$timezone);$start=$today->modify('-'.($days-1).' days');$orders=wc_get_orders(['limit'=>-1,'date_created'=>'>='.$start->format('Y-m-d H:i:s'),'orderby'=>'date','order'=>'ASC']);$paid_statuses=wc_get_is_paid_statuses();$status_counts=[];$daily=[];$products=[];$revenue=0.0;$paid_count=0;
        for($i=0;$i<$days;$i++){$date=$start->modify('+'.$i.' days')->format('Y-m-d');$daily[$date]=0.0;}
        foreach($orders as $order){$status=$order->get_status();$status_counts[$status]=($status_counts[$status]??0)+1;if(!in_array($status,$paid_statuses,true))continue;$paid_count++;$net=max(0,(float)$order->get_total()-(float)$order->get_total_refunded());$revenue+=$net;$created=$order->get_date_created();if($created){$key=$created->date('Y-m-d');if(array_key_exists($key,$daily))$daily[$key]+=$net;}foreach($order->get_items() as $item){$product_id=$item->get_product_id();if(!$product_id)continue;if(!isset($products[$product_id]))$products[$product_id]=['product_id'=>$product_id,'name'=>$item->get_name(),'quantity'=>0,'revenue'=>0.0];$products[$product_id]['quantity']+=(int)$item->get_quantity();$products[$product_id]['revenue']+=(float)$item->get_total();}}
        uasort($products,static fn($a,$b)=>$b['quantity']<=>$a['quantity']);$top=array_slice(array_values($products),0,10);$series=[];foreach($daily as $date=>$amount)$series[]=['date'=>$date,'revenue'=>wc_format_decimal($amount,2)];$statuses=[];foreach(wc_get_order_statuses() as $key=>$label){$value=str_replace('wc-','',$key);$statuses[]=['status'=>$value,'label'=>$label,'count'=>(int)($status_counts[$value]??0)];}
        return rest_ensure_response(['days'=>$days,'currency'=>get_woocommerce_currency(),'revenue'=>wc_format_decimal($revenue,2),'orders_count'=>count($orders),'paid_orders_count'=>$paid_count,'average_order_value'=>wc_format_decimal($paid_count?$revenue/$paid_count:0,2),'refunded'=>wc_format_decimal(array_sum(array_map(static fn($order)=>(float)$order->get_total_refunded(),$orders)),2),'daily'=>$series,'statuses'=>$statuses,'top_products'=>$top,'generated_at'=>current_time(DATE_ATOM)]);
    }
