    private static function apply_coupon(WC_Coupon $coupon,array $p){if(array_key_exists('code',$p))$coupon->set_code(wc_format_coupon_code($p['code']));if(array_key_exists('description',$p))$coupon->set_description(sanitize_textarea_field((string)$p['description']));if(array_key_exists('discount_type',$p)){if(!in_array($p['discount_type'],['percent','fixed_cart','fixed_product'],true))return new WP_Error('invalid_discount_type','نوع تخفیف معتبر نیست.',['status'=>422]);$coupon->set_discount_type($p['discount_type']);}if(array_key_exists('amount',$p))$coupon->set_amount(max(0,(float)wc_format_decimal($p['amount'])));if(array_key_exists('usage_limit',$p))$coupon->set_usage_limit(max(0,(int)$p['usage_limit']));if(array_key_exists('individual_use',$p))$coupon->set_individual_use(rest_sanitize_boolean($p['individual_use']));if(array_key_exists('free_shipping',$p))$coupon->set_free_shipping(rest_sanitize_boolean($p['free_shipping']));if(array_key_exists('minimum_amount',$p))$coupon->set_minimum_amount(wc_format_decimal($p['minimum_amount']));if(array_key_exists('maximum_amount',$p))$coupon->set_maximum_amount(wc_format_decimal($p['maximum_amount']));if(array_key_exists('date_expires',$p))$coupon->set_date_expires($p['date_expires']?:null);return $coupon;}
