    public static function media(WP_REST_Request $request){$limit=min(50,max(1,(int)($request->get_param('limit')?:30)));$page=max(1,(int)($request->get_param('page')?:1));$query=new WP_Query(['post_type'=>'attachment','post_status'=>'inherit','post_mime_type'=>'image','posts_per_page'=>$limit,'paged'=>$page,'orderby'=>'date','order'=>'DESC']);return rest_ensure_response(['items'=>array_map([self::class,'serialize_media'],$query->posts),'total'=>(int)$query->found_posts,'pages'=>(int)$query->max_num_pages,'page'=>$page]);}
    public static function upload_media(WP_REST_Request $request){$p=(array)$request->get_json_params();$filename=sanitize_file_name((string)($p['filename']??''));$mime=sanitize_mime_type((string)($p['mime_type']??''));$encoded=(string)($p['content_base64']??'');if($filename===''||strpos($mime,'image/')!==0||$encoded==='')return new WP_Error('invalid_media','نام، نوع تصویر و محتوای فایل الزامی است.',['status'=>422]);$bytes=base64_decode($encoded,true);if($bytes===false||strlen($bytes)>10*MB_IN_BYTES)return new WP_Error('invalid_media_size','تصویر نامعتبر یا بزرگ‌تر از ۱۰ مگابایت است.',['status'=>422]);$allowed=get_allowed_mime_types();if(!in_array($mime,$allowed,true))return new WP_Error('media_type_not_allowed','نوع فایل مجاز نیست.',['status'=>422]);$upload=wp_upload_bits($filename,null,$bytes);if(!empty($upload['error']))return new WP_Error('media_upload_failed',$upload['error'],['status'=>500]);$attachment_id=wp_insert_attachment(['post_mime_type'=>$mime,'post_title'=>sanitize_text_field(pathinfo($filename,PATHINFO_FILENAME)),'post_status'=>'inherit'],$upload['file']);if(is_wp_error($attachment_id))return $attachment_id;require_once ABSPATH.'wp-admin/includes/image.php';wp_update_attachment_metadata($attachment_id,wp_generate_attachment_metadata($attachment_id,$upload['file']));WM_Logs::add('media_uploaded','تصویر جدید از اپ بارگذاری شد.',['attachment_id'=>$attachment_id]);return new WP_REST_Response(self::serialize_media(get_post($attachment_id)),201);}
